<script setup lang="ts">
import { formatAdminDate } from "~/utils/format-date"
const PAGE_SIZE=25;const sessionOffset=ref(0);const historyOffset=ref(0);const userId=ref(""); const summary=ref<any>(); const sessions=ref<any>(); const history=ref<any>(); const error=ref(""); const busy=ref(false)
const sessionItems=computed(()=>sessions.value?.items??[])
const visibleSessions=computed(()=>sessionItems.value.slice(sessionOffset.value,sessionOffset.value+PAGE_SIZE))
const historyItems=computed(()=>history.value?.events??[])
const visibleHistory=computed(()=>historyItems.value.slice(historyOffset.value,historyOffset.value+PAGE_SIZE))
async function inspect(){ if(!userId.value.trim())return; sessionOffset.value=0;historyOffset.value=0;busy.value=true;error.value="";try{[summary.value,sessions.value,history.value]=await Promise.all([$fetch(`/api/provider/security/${encodeURIComponent(userId.value)}/summary`),$fetch(`/api/provider/security/${encodeURIComponent(userId.value)}/sessions`),$fetch(`/api/provider/security/${encodeURIComponent(userId.value)}/history`)])}catch(e:any){error.value=e?.data?.message??e?.statusMessage??e?.message??"Security inspection failed."}finally{busy.value=false}}
async function command(action:string){if(!userId.value||!confirm(`Execute ${action} for this identity?`))return;busy.value=true;error.value="";try{await $fetch(`/api/provider/security/${encodeURIComponent(userId.value)}/${action}`,{method:"POST"});await inspect()}catch(e:any){error.value=e?.data?.message??e?.statusMessage??e?.message??"Security action failed."}finally{busy.value=false}}
async function revoke(sessionId:string){if(!confirm("Revoke this session?"))return;await $fetch(`/api/provider/security/${encodeURIComponent(userId.value)}/sessions/${encodeURIComponent(sessionId)}/revoke`,{method:"POST"});await inspect()}
</script><template><div class="page-stack"><div class="page-heading"><div><p class="eyebrow">SECURITY</p><h1>Identity Security</h1><p>Investigate and respond using IAM-owned security administration.</p></div></div><section class="panel"><div class="admin-filters"><input v-model="userId" placeholder="Identity ID" @keyup.enter="inspect"><button class="secondary-button" :disabled="busy" @click="inspect">Inspect</button></div><div v-if="error" class="alert alert--error">{{error}}</div></section><template v-if="summary"><section class="panel"><div class="panel-heading"><div><p class="eyebrow">SECURITY SUMMARY</p><h2>{{summary.identityStatus}}</h2></div><span class="pill" :class="{'pill--good':summary.authentication?.signInEligible}">{{summary.authentication?.signInEligible?'Sign-in eligible':'Sign-in blocked'}}</span></div><div class="summary-grid"><div><span>Sessions</span><strong>{{summary.sessions?.total??0}}</strong></div><div><span>Active</span><strong>{{summary.sessions?.active??0}}</strong></div><div><span>Verification</span><strong>{{summary.verification?.state??'—'}}</strong></div><div><span>Recovery</span><strong>{{summary.recovery?.state??'—'}}</strong></div></div><div class="command-bar"><button class="secondary-button" @click="command('revoke-all')">Revoke all sessions</button><button class="secondary-button" @click="command('recovery')">Initiate recovery</button><button v-if="summary.identityStatus!=='suspended'" class="danger-button" @click="command('suspend')">Suspend identity</button><button v-else class="secondary-button" @click="command('reactivate')">Reactivate identity</button></div></section><section class="panel"><div class="panel-heading"><div><p class="eyebrow">SESSIONS</p><h2>Identity sessions</h2></div></div><div class="table-wrap"><table><thead><tr><th>Status</th><th>Issued</th><th>Expires</th><th>Ended</th><th></th></tr></thead><tbody><tr v-for="s in visibleSessions" :key="s.sessionId"><td><span class="pill">{{s.status}}</span></td><td>{{formatAdminDate(s.issuedAt)}}</td><td>{{formatAdminDate(s.expiresAt)}}</td><td>{{formatAdminDate(s.endedAt)}}</td><td><button v-if="s.status==='active'" class="text-button" @click="revoke(s.sessionId)">Revoke</button></td></tr></tbody></table></div><AppPagination :total="sessionItems.length" :offset="sessionOffset" :limit="PAGE_SIZE" @change="sessionOffset=$event" /></section><section class="panel"><div class="panel-heading"><div><p class="eyebrow">SECURITY HISTORY</p><h2>Authentication & lifecycle events</h2></div></div><div class="table-wrap"><table><thead><tr><th>Event</th><th>Occurred</th><th>Resource</th><th>Correlation</th></tr></thead><tbody><tr v-for="e in visibleHistory" :key="`${e.eventType}:${e.occurredAt}`"><td>{{e.eventType}}</td><td>{{formatAdminDate(e.occurredAt)}}</td><td class="mono">{{e.aggregateId}}</td><td class="mono">{{e.correlationId??'—'}}</td></tr></tbody></table></div><AppPagination :total="historyItems.length" :offset="historyOffset" :limit="PAGE_SIZE" @change="historyOffset=$event" /></section></template></div></template>